 uint8_t *mo=mission_obj(base),*pr=mission_profile(base);if(!pr)return;
 uint8_t *set=mission_set(base,s,*(int32_t*)(mo+0x100c));if(!set)return;
 if(!u3x_take_mission(mo,pr,set,*(uint32_t*)(mo+0x1010),(uint8_t(*)(uint8_t*,uint8_t*,int))s->natives[NATIVE_MISSION_CAN],mission_done,(int64_t(*)(int64_t*))*(uintptr_t*)&X.eb[4]))return;   /* v7.115 C++ */
