 int bad=n>0x10000u;
 if(!bad&&n){uint64_t a=*(uint64_t*)(in+0x658),b=*(uint64_t*)(in+0x668);if((a&&!sg_ptr(a))||(b&&!sg_ptr(b)))bad=1;}
 if(!bad)return 0;
 uint32_t k=X.sg[1]++&3;X.sgd[48+k*2]=(uint64_t)in;X.sgd[49+k*2]=ret;
 if(!X.sg[3]){X.sg[3]=n?n:1;X.sgd[0]=(uint64_t)in;
  for(int i=0;i<12;i++)X.sgd[1+i]=*(uint64_t*)(in+i*8);
  for(int i=0;i<6;i++)X.sgd[13+i]=*(uint64_t*)(in+0x640+i*8);
  uint64_t ob=*(uint64_t*)(in+0x20);X.sgd[19]=ob;
  if(sg_ptr(ob)){for(int i=0;i<12;i++)X.sgd[20+i]=*(uint64_t*)(ob+i*8);
   uint64_t md=*(uint64_t*)(ob+0x48);X.sgd[32]=md;
   if(sg_ptr(md))for(int i=0;i<14;i++)X.sgd[33+i]=*(uint64_t*)(md+i*8);}
  if(ret==base+0x125840fu||ret==base+0x125843fu){uint8_t *pr=in-0xb0;for(int i=0;i<24;i++)X.sgo[i]=*(uint64_t*)(pr+i*8);}
  else sg_capture_ss(base,in,regs);}
