  sd[13]=clk?*(uint32_t*)(clk+0xc):0;sd[14]=*(uint32_t*)(base+0x17b4ba4);sd[15]=c7;sd[16]=sd[1];
  sd[17]=*(uint32_t*)(base+0x17d6438);sd[18]=*(uint32_t*)(base+0x17d7704);sd[19]=*(uint32_t*)(base+0x17d7708);
