 OL.fd=0;OL.rx_len=OL.tx_len=0;OL.party=0;OL.pcount=0;OL.st=st;
 for(int i=0;i<8;i++)if(OL.tk[i].used&&OL.tk[i].left){OL.tk[i].left=0;OL.tk[i].result=-1;if(OL.tk[i].nopoll)OL.tk[i].used=0;}   /* b008: no connection = PS3's "could not connect" */
