  if(rp_starts(p,"session="))X.ec[96]=rp_starts(p+8,"frames")?1u:0u;   /* sw01 */
  if(rp_starts(p,"upnp="))X.ec[97]=rp_starts(p+5,"1")?1u:p[5]==48?2u:0u;   /* pl01 */
