   if(h24_ad(mn,bitsf(h24_tab[i].mn))<lim&&h24_ad(mx,bitsf(h24_tab[i].mx))<lim&&h24_ad(fb,bitsf(h24_tab[i].fb))<lim){hit=i;break;}
